const CONTACT_WORKER_URL = 'https://contact-verify.lizberries.workers.dev';

async function sendEmail(event) {
  if (event) {
    event.preventDefault();
  }

  const messageText = document.getElementById('responseMessageText');
  const messageBox = document.getElementById('responseMessage');
  const submitBtn = document.getElementById('send');
  const form = document.getElementById('contactForm');

  const payload = {
    first_name: document.getElementById('firstname').value,
    last_name: document.getElementById('lastname').value,
    e_mail: document.getElementById('emailaddress').value,
    subject: document.getElementById('subject').value,
    message: document.getElementById('message').value,
    source: 'thelizards'
  };

  submitBtn.disabled = true;
  messageText.innerText = 'Sending verification email...';
  messageText.className = 'text-info';
  messageBox.style.display = 'block';

  try {
    const response = await fetch(`${CONTACT_WORKER_URL}/request`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(payload)
    });

    let responseData = null;
    try {
      responseData = await response.json();
    } catch (parseError) {
      responseData = null;
    }

    if (!response.ok) {
      throw new Error((responseData && responseData.error) || `Request failed (${response.status})`);
    }

    if (responseData && responseData.success !== true) {
      throw new Error(responseData.error || 'Verification email not accepted');
    }

    messageText.innerText = 'Check your email to confirm the message.';
    messageText.className = 'text-success';
    if (form && typeof form.reset === 'function') {
      form.reset();
    } else if (form) {
      form.querySelectorAll('input, textarea').forEach((field) => {
        field.value = '';
      });
    }
  } catch (error) {
    console.error('Contact error:', error);
    messageText.innerText = error.message || 'Unable to send verification email. Please try again.';
    messageText.className = 'text-danger';
  } finally {
    submitBtn.disabled = false;
    setTimeout(function () {
      messageBox.style.display = 'none';
    }, 6000);
  }
}
